            stack.append((i-1, j))
            stack.append((i+1, j))
            stack.append((i, j-1))
            stack.append((i, j+1))
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count

