def solve(grid):
    """Count number of islands (connected 1s) in a 2D grid.
    Uses DFS to mark visited cells. Adjacent cells are up/down/left/right.
    """
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            for dr, dc in ((1,0), (-1,0), (0,1), (0,-1)):
                ni, nj = i+dr, j+dc
                if 0 <= ni < rows and 0 <= nj < cols:
                    if not visited[ni][nj] and grid[ni][nj] == 1:
                        stack.append((ni, nj))
    islands = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                islands += 1
                dfs(i, j)
    return islands

