    """Compute the Levenshtein edit distance between strings a and b.
    Operations allowed: insertion, deletion, substitution, each cost 1.
    """
    # If one of the strings is empty, distance is the length of the other.
    if not a:
        return len(b)
    if not b:
        return len(a)
    n, m = len(a), len(b)
    # Use two rows to save memory.
    prev = list(range(m + 1))  # distance for empty a prefix
    for i in range(1, n + 1):
        curr = [i] + [0] * m
        ai = a[i - 1]
        for j in range(1, m + 1):
            if ai == b[j - 1]:
                cost = 0
            else:
                cost = 1
            # Minimum of deletion, insertion, substitution
            curr[j] = min(prev[j] + 1,        # deletion
                         curr[j - 1] + 1,    # insertion
                         prev[j - 1] + cost)  # substitution
        prev = curr
    return prev[m]

