{"task_id": "T34", "code": "def solve(s: str) -> bool:
    """Check if brackets in the string are balanced and properly nested.
    Considers (), [], {} and ignores other characters.
    """
    matching = {')': '(', ']': '[', '}': '{'}
    opening = set(matching.values())
    stack = []
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in matching:
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()
    return not stack
