{"task_id": "T35", "code": "def solve(grid):
    """Count islands in a possibly jagged grid of 0s and 1s.
    Cells are adjacent horizontally and vertically (no diagonal).
    Handles rows of differing lengths.
    """
    if not grid:
        return 0
    visited = set()
    m = len(grid)
    def neighbors(i, j):
        # Up
        if i > 0 and j < len(grid[i-1]):
            yield i-1, j
        # Down
        if i+1 < m and j < len(grid[i+1]):
            yield i+1, j
        # Left
        if j > 0:
            yield i, j-1
        # Right
        if j+1 < len(grid[i]):
            yield i, j+1
    def dfs(start_i, start_j):
        stack = [(start_i, start_j)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            visited.add((i, j))
            for ni, nj in neighbors(i, j):
                if (ni, nj) not in visited and grid[ni][nj] == 1:
                    stack.append((ni, nj))
    islands = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and (i, j) not in visited:
                dfs(i, j)
                islands += 1
    return islands
