def solve(tokens):
    """Evaluate a reverse Polish notation expression.
    Tokens can be strings or integers representing numbers, and operators '+', '-', '*', '/'.
    Division truncates toward zero.
    """
    stack = []
    ops = {'+', '-', '*', '/'}
    for tok in tokens:
        # Normalize token to string for operator check
        if isinstance(tok, str) and tok in ops:
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # '/'
                # Truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            # Operand: convert to int (handles both int and numeric strings)
            stack.append(int(tok))
    return stack[0] if stack else 0

