def solve(nums):
    """Return length of the longest strictly increasing subsequence.
    Uses patience sorting with binary search, O(n log n).
    """
    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subseq of length i+1
    for x in nums:
        # Find first tail >= x for strictly increasing subsequence
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

